D=/private/tmp/claude-501/-Users-kanaanzafar-Documents-kanaan-zafar-calculator/2b0e9127-903f-44bb-b090-ef5d425ce562/scratchpad; cat > $D/number-vs-bigint.mjs <<'EOF'
// Scratch check: is integer Number arithmetic exact within the approved input limits?
const MAX_SUB = 99_999_999, MAX_TAX = 30_000, MAX_TIP = 100_000, SCALE = 100_000;
const halfUpN = (n, d) => Math.floor((2 * n + d) / (2 * d));
const halfUpB = (n, d) => (2n * n + d) / (2n * d);
const calcN = (s, tx, tp, p) => {
  const tax = halfUpN(s * tx, SCALE), tip = halfUpN(s * tp, SCALE), tot = s + tax + tip;
  return [tax, tip, tot, Math.floor(tot / p), tot % p];
};
const calcB = (s, tx, tp, p) => {
  const [S, X, T, P] = [s, tx, tp, p].map(BigInt), D = BigInt(SCALE);
  const tax = halfUpB(S * X, D), tip = halfUpB(S * T, D), tot = S + tax + tip;
  return [tax, tip, tot, tot / P, tot % P].map(Number);
};
const largest = MAX_SUB * MAX_TIP, halfUpArg = 2 * largest + 2 * SCALE;
console.log('largest product        ', largest.toLocaleString());
console.log('largest half-up operand', halfUpArg.toLocaleString());
console.log('MAX_SAFE_INTEGER       ', Number.MAX_SAFE_INTEGER.toLocaleString());
console.log('headroom factor        ', Math.floor(Number.MAX_SAFE_INTEGER / halfUpArg));
const edges = { s: [1, 2, 99, 100, 101, 999, 1000, 12345, 99_999_998, MAX_SUB], tx: [0, 1, 4999, 5000, 8875, 29_999, MAX_TAX], tp: [0, 1, 15_000, 18_000, 99_999, MAX_TIP], p: [1, 2, 3, 7, 99, 100] };
let checked = 0, mismatches = 0;
const check = (s, tx, tp, p) => { checked++; const a = calcN(s, tx, tp, p), b = calcB(s, tx, tp, p); if (a.some((v, i) => v !== b[i])) { mismatches++; if (mismatches < 5) console.log('MISMATCH', s, tx, tp, p, a, b); } };
for (const s of edges.s) for (const tx of edges.tx) for (const tp of edges.tp) for (const p of edges.p) check(s, tx, tp, p);
const r = (max, min = 0) => min + Math.floor(Math.random() * (max - min + 1));
for (let i = 0; i < 3_000_000; i++) check(r(MAX_SUB, 1), r(MAX_TAX), r(MAX_TIP), r(100, 1));
// Exact half-cent ties at the top of the range (where float error would show first)
for (let s = MAX_SUB - 200_000; s <= MAX_SUB; s++) check(s, 5_000, 50_000, 3);
console.log(`checked ${checked.toLocaleString()} cases, mismatches: ${mismatches}`);
EOF
node $D/number-vs-bigint.mjs

