D=/private/tmp/claude-501/-Users-kanaanzafar-Documents-kanaan-zafar-calculator/2b0e9127-903f-44bb-b090-ef5d425ce562/scratchpad; cat > $D/examples.mjs <<'EOF'
// Scratch check of every worked example used in the acceptance criteria
const hu = (n, d) => (2n * n + d) / (2n * d);
const f = c => '$' + (c / 100n).toLocaleString('en-US') + '.' + String(c % 100n).padStart(2, '0');
const run = (label, s, tx, tp, p) => {
  const tax = hu(s * tx, 100000n), tip = hu(s * tp, 100000n), tot = s + tax + tip;
  const base = tot / p, r = tot % p;
  const shares = Array.from({ length: Number(p) }, (_, i) => base + (BigInt(i) < r ? 1n : 0n));
  const sum = shares.reduce((a, b) => a + b, 0n);
  console.log(label, 'tax', f(tax), 'tip', f(tip), 'total', f(tot), '| r =', r, '| P1', f(shares[0]), '| others', [...new Set(shares.slice(1).map(f))].join(' / ') || '-', '| collect', f(tot - shares[0]), '| sum ok', sum === tot);
};
run('A', 10000n, 8875n, 18000n, 3n);
run('A4', 10000n, 8875n, 18000n, 4n);
run('A tip20', 10000n, 8875n, 20000n, 3n);
run('B', 10001n, 0n, 0n, 3n);
run('C', 10000n, 0n, 0n, 3n);
run('D', 9000n, 0n, 0n, 3n);
run('E', 10000n, 8875n, 18000n, 1n);
run('F', 1n, 8875n, 18000n, 3n);
run('G', 99999999n, 30000n, 100000n, 100n);
run('H', 1234n, 8875n, 18000n, 3n);
run('I', 1000n, 30000n, 100000n, 2n);
run('min', 1n, 0n, 0n, 1n);
run('12.', 1200n, 0n, 0n, 2n);
run('.5', 50n, 0n, 0n, 1n);
console.log('tip on post-tax would be', f(hu((10000n + 888n) * 18000n, 100000n)));
EOF
node $D/examples.mjs

