      shares: ['Person 1 (paid the bill): $33.34', 'Persons 2–3: $33.33 each'],
      collect: '$66.66',
    });
  });

  it('AC3 two leftover cents both go to Person 1', () => {
    expect(results({ subtotal: '100.01', taxRate: '0', tipRate: '0', people: '3' })).toMatchObject({
