    ['8.8.75', invalid(m.format)],
    ['1,000.5', invalid(m.format)],
    ['.', pending(m.format)],
    [',', pending(m.format)],
    ['8.8755', invalid(m.decimals)],
    ['30.001', invalid(m.max)],
