/* Mobile first: one column by default, two columns from 768px. */

:root {
  --bg: #f6f5f1;
  --surface: #ffffff;
  --text: #1c1d1f;
  --muted: #5d6166;
  --border: #d9d8d2;
  --accent: #126b55;
  --accent-soft: #e5f2ed;
  --focus: #1f5fd1;
  --error: #b42318;
  --error-soft: #fdecea;
  --radius: 14px;
  --shadow: 0 1px 2px rgb(0 0 0 / 0.05), 0 4px 16px rgb(0 0 0 / 0.04);

  color-scheme: light dark;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16181b;
    --surface: #1f2226;
    --text: #eceef0;
    --muted: #a3a8ae;
    --border: #3a3f45;
    --accent: #4cc9a2;
    --accent-soft: #1d3a31;
    --focus: #7aa7ff;
    --error: #ff8a80;
    --error-soft: #3d2120;
    --shadow: none;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
}

.app {
  max-width: 960px;
  margin: 0 auto;
  padding: 20px 16px 40px;
}

.app-header {
  margin-bottom: 16px;
}

h1 {
  margin: 0;
  font-size: 1.6rem;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.tagline {
  margin: 4px 0 0;
  color: var(--muted);
}

.layout {
  display: grid;
  gap: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px 16px;
}

.section-heading {
  margin: 0 0 12px;
  font-size: 1.05rem;
}

/* Form */

.field {
  margin-bottom: 16px;
  min-width: 0;
}

.field:last-child {
  margin-bottom: 0;
}

.field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
}

.input-wrap {
  position: relative;
}

.affix {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--muted);
  pointer-events: none;
}

input {
  width: 100%;
  min-height: 48px;
  padding: 10px 14px;
  /* 16px or more stops iOS Safari zooming in on focus. */
  font: inherit;
  font-size: 1.125rem;
  font-variant-numeric: tabular-nums;
  color: var(--text);
  background: var(--surface);
  border: 1.5px solid var(--border);
  border-radius: 10px;
  appearance: none;
}

.has-prefix input {
  padding-left: 30px;
}

input::placeholder {
  color: var(--muted);
  opacity: 0.7;
}

input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 1px;
  border-color: var(--focus);
}

input[aria-invalid='true'] {
  border-color: var(--error);
}

.hint {
  margin: 6px 0 0;
  font-size: 0.875rem;
  color: var(--muted);
}

.error {
  margin: 6px 0 0;
  padding: 6px 10px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--error);
  background: var(--error-soft);
  border-radius: 8px;
}

.error[hidden] {
  display: none;
}

/* Results */

.results-empty {
  margin: 0;
  color: var(--muted);
}

.breakdown {
  margin: 0;
}

.row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
}

.row dt {
  color: var(--muted);
}

.row dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.row.total {
  border-bottom: none;
  font-size: 1.15rem;
  font-weight: 700;
}

.row.total dt {
  color: var(--text);
}

.sub-heading {
  margin: 16px 0 8px;
  font-size: 0.95rem;
}

.shares {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.shares li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px 12px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
}

.shares li.payer {
  background: var(--accent-soft);
  border-color: transparent;
}

.share-amount {
  font-weight: 700;
  font-size: 1.1rem;
  font-variant-numeric: tabular-nums;
}

.collect {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px 12px;
  margin-top: 16px;
  padding: 14px;
  border-radius: 10px;
  background: var(--accent);
  color: var(--surface);
}

.collect-label {
  font-weight: 600;
}

.collect-amount {
  font-weight: 800;
  font-size: 1.25rem;
  font-variant-numeric: tabular-nums;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (min-width: 768px) {
  .app {
    padding: 40px 24px;
  }

  h1 {
    font-size: 2rem;
  }

  .layout {
    grid-template-columns: 1fr 1fr;
    align-items: start;
    gap: 24px;
  }

  .card {
    padding: 24px;
  }

  .results {
    position: sticky;
    top: 24px;
  }
}

